```swift
  nonisolated private func fillGap(
    from start: CMTime, to end: CMTime,
    channelCount: Int, sampleRate: Double,
    input: AVAssetWriterInput
  ) -> Int {
    let gapSeconds = CMTimeGetSeconds(end - start)
    let gapSamples = Int(gapSeconds * sampleRate)
    guard gapSamples > 0 else { return 0 }
    let chunkSize = 1024
    var written = 0
    var offset = 0
    while offset < gapSamples {
      let count = min(chunkSize, gapSamples - offset)
      let pts = CMTimeAdd(start, CMTime(value: Int64(offset), timescale: Int32(sampleRate)))
      guard let sb = Self.makeSilentSampleBuffer(
          channelCount: channelCount, sampleCount: count,
          sampleRate: sampleRate, presentationTimeStamp: pts)
      else {
        Log.error(Log.recorder, "recorder", "silence buffer creation failed at offset \(offset)/\(gapSamples)")
        break
      }
      guard input.isReadyForMoreMediaData else {
        Log.info(Log.recorder, "recorder", "silence fill interrupted by back-pressure at \(written)/\(gapSamples / chunkSize) chunks")
        break
      }
      if input.append(sb) { written += 1 }
      else {
        Log.error(Log.recorder, "recorder", "silence append failed at offset \(offset)/\(gapSamples)")
        break
      }
      offset += count
    }
    return written
  }
```

