// MARK: - Gap Detection Logic

@Test("gap below threshold is not detected", arguments: [0.001, 0.005, 0.009, 0.01])
func gapBelowThreshold(gapSeconds: Double) {
  // Gaps <= 10ms should not trigger filling. Verify via bufferEndTime continuity.
  let firstEnd = CMTime(value: 48000, timescale: 48000)  // 1.0s
  let nextPts = CMTimeAdd(firstEnd, CMTime(seconds: gapSeconds, preferredTimescale: 48000))
  let gap = CMTimeGetSeconds(nextPts - firstEnd)
  #expect(gap <= 0.01, "Gap \(gap)s should be at or below 10ms threshold")
}

@Test("gap above threshold is detected", arguments: [0.011, 0.05, 0.5, 2.0, 10.0])
func gapAboveThreshold(gapSeconds: Double) {
  let firstEnd = CMTime(value: 48000, timescale: 48000)  // 1.0s
  let nextPts = CMTimeAdd(firstEnd, CMTime(seconds: gapSeconds, preferredTimescale: 48000))
  let gap = CMTimeGetSeconds(nextPts - firstEnd)
  #expect(gap > 0.01, "Gap \(gap)s should be above 10ms threshold")
}

@Test("negative gap (overlap) is not treated as a gap")
func negativeGapIgnored() {
  let firstEnd = CMTime(value: 48000, timescale: 48000)  // 1.0s
  let nextPts = CMTime(value: 47000, timescale: 48000)  // 0.979s (overlap)
  let gap = CMTimeGetSeconds(nextPts - firstEnd)
  #expect(gap < 0, "Negative gap should not trigger filling")
}

// MARK: - Gap Size Calculations

@Test("gap sample count matches expected for typical device switch gaps")
func gapSampleCountDeviceSwitch() {
  // Real-world: device switches cause gaps of 0.5-3s
  let testCases: [(gapSec: Double, expectedSamples: Int)] = [
    (0.5, 24000),  // 500ms
    (1.0, 48000),  // 1s
    (2.16, 103680),  // 2.16s (observed in production)
    (3.0, 144000),  // 3s
  ]
  for (gapSec, expectedSamples) in testCases {
    let computed = Int(gapSec * 48000)
    #expect(
      computed == expectedSamples,
      "Gap \(gapSec)s: expected \(expectedSamples) samples, got \(computed)")
  }
}
